import type { ComponentPropsWithoutRef, ElementType, ReactNode } from "react";

/** Standard Craft Matrix block fields used by Drive CMS wrappers. */
export interface CmsBlockData {
	id: string;
	uid: string;
	title: string;
	headline?: string | null;
	copy?: string | null;
	hero?: Array<{
		url: string;
		alt?: string | null;
		width?: number;
		height?: number;
	}>;
	button?: Array<{
		text?: string | null;
		linkText?: string | null;
		url?: string | null;
		linkUrl?: string | null;
		newWindow?: string | boolean | null;
	}>;
}

/**
 * CmsBlockData aligns with SharedBlockContent in @/lib/component-content:
 *   title, headline, copy → copy fields
 *   hero[0]               → image
 *   button[0]             → button
 */

export type EditableMode = "inline" | "panel" | "focus";

export interface CmsFieldMapping {
	cmsField: keyof CmsBlockData | "componentHandle";
	prop: string;
	label: string;
	editable?: EditableMode;
	/** e.g. "comma-list" to split headline into string[] */
	format?: "comma-list";
}

export interface CmsComponentMeta {
	enabled: boolean;
	usesBlockStyles?: boolean;
	fields: CmsFieldMapping[];
}

export interface EditableFieldProps {
	subfield: string;
	label: string;
	inline?: boolean;
	panelOnly?: boolean;
	className?: string;
	as?: ElementType;
	children: ReactNode;
}

export type EditableComponent = (
	props: EditableFieldProps,
) => ReactNode;

export interface CmsBlockContext {
	fieldHandle: string;
	blockId: string;
	blockUid: string;
	entryId?: string;
	Editable: EditableComponent;
}

export type CmsBlockProps<TProps extends Record<string, unknown> = Record<string, unknown>> =
	CmsBlockContext & {
		data: CmsBlockData;
	} & TProps;

export type CmsBlockComponent<TProps extends Record<string, unknown> = Record<string, unknown>> =
	(props: CmsBlockProps<TProps>) => ReactNode;

export function mapCommaList(value?: string | null): string[] {
	if (!value?.trim()) {
		return [];
	}

	return value
		.split(/[,;]+/)
		.map((part) => part.trim())
		.filter(Boolean);
}

export function getBlockButton(data: CmsBlockData) {
	return data.button?.[0];
}

export function getBlockImage(data: CmsBlockData) {
	return data.hero?.[0];
}

"use client";

import React from "react";

import {
	CardBody,
	CardContainer,
	CardItem,
} from "@/registry/open-source/3d-card";

import {
	CmsBlockComponent,
	getBlockButton,
	getBlockImage,
} from "./_types";

/**
 * Library-shaped CMS block — copy to component library: registry/cms/3d-card.block.tsx
 * Adjust Card import path to match library aliases (@/registry/open-source/3d-card).
 */
export const threeDCardCmsMeta = {
	enabled: true,
	usesBlockStyles: true,
	fields: [
		{ cmsField: "title", prop: "title", label: "Card title", editable: "inline" },
		{ cmsField: "headline", prop: "subtitle", label: "Subtitle", editable: "inline" },
		{ cmsField: "hero", prop: "image", label: "Card image", editable: "focus" },
		{ cmsField: "button", prop: "button", label: "Call to action", editable: "focus" },
	],
} as const;

export const ThreeDCardCmsBlock: CmsBlockComponent = ({
	data,
	Editable,
}) => {
	const image = getBlockImage(data);
	const button = getBlockButton(data);

	return (
		<CardContainer className="inter-var">
			<CardBody className="relative h-auto w-auto rounded-xl border border-black/[0.1] bg-gray-50 p-6 dark:border-white/[0.2] dark:bg-black dark:hover:shadow-2xl">
				<Editable subfield="title" label="Card title" inline>
					<CardItem
						translateZ="50"
						className="text-xl font-bold text-neutral-600 dark:text-white"
					>
						{data.title}
					</CardItem>
				</Editable>
				{data.headline ? (
					<Editable subfield="headline" label="Subtitle" inline>
						<CardItem
							as="p"
							translateZ="60"
							className="mt-2 max-w-sm text-sm text-neutral-500 dark:text-neutral-300"
						>
							{data.headline}
						</CardItem>
					</Editable>
				) : null}
				<Editable subfield="hero" label="Card image">
					<CardItem translateZ="100" className="mt-4 w-full">
						{image ? (
							<img
								src={image.url}
								height={image.height}
								width={image.width}
								className="h-60 w-full rounded-xl object-cover group-hover/card:shadow-xl"
								alt={image.alt || data.title}
							/>
						) : (
							<div className="flex h-60 w-full items-center justify-center rounded-xl bg-neutral-200 text-sm text-neutral-500 dark:bg-neutral-800">
								Add an image
							</div>
						)}
					</CardItem>
				</Editable>
				{button ? (
					<Editable subfield="button" label="Call to action">
						<div className="mt-6 flex items-center justify-between">
							<CardItem
								translateZ={20}
								as="a"
								href={button.url || button.linkUrl || "#"}
								target={button.newWindow ? "_blank" : undefined}
								rel={
									button.newWindow ? "noopener noreferrer" : undefined
								}
								className="rounded-xl px-4 py-2 text-xs font-normal dark:text-white"
							>
								{button.text || button.linkText}
							</CardItem>
						</div>
					</Editable>
				) : null}
			</CardBody>
		</CardContainer>
	);
};
